-- Our Tasks: complete database setup for project jwhuaaxrymdqwanwthvg.
-- Generated by scripts/make-setup-sql.py. Run once in the SQL Editor; safe to run again.

-- ======== schema.sql ========
-- Our Tasks: database structure and access rules for Supabase.
-- Run once: Supabase dashboard > SQL Editor > New query > paste this file > Run.
--
-- Access model
--   * Sign-ups are switched off in the dashboard; the only users are the two people invited there.
--   * Every table allows signed-in users only (row level security). The public "publishable" key
--     in the app alone cannot read or write anything.
--   * Private tasks are visible only to their owner, enforced by the database, not by the app.
--
-- Column names are snake_case; the app maps them to its camelCase fields
-- (parent_id <-> parentId). "author" is stored for the app's "by", and "sort_order" for "order",
-- because BY and ORDER are reserved words in SQL.
-- Times are milliseconds since 1970 (bigint) and due dates are 'YYYY-MM-DD' text, as in the app.

-- ---------- tables ----------

create table if not exists public.tasks (
  id           text primary key default gen_random_uuid()::text,
  title        text not null,
  status       text not null default 'todo'   check (status in ('todo', 'doing', 'done')),
  assignee     text not null default ''       check (assignee in ('', 'a', 'b', 'both')),
  priority     text not null default 'normal' check (priority in ('low', 'normal', 'high')),
  due          text not null default '',
  repeat       text not null default '',
  parent_id    text not null default '',
  notes        text not null default '',
  sort_order   double precision not null default 0,
  created_at   bigint not null default 0,
  assigned_by  text not null default '',
  assigned_at  bigint not null default 0,
  archived     boolean not null default false,
  archived_at  bigint,
  private      boolean not null default false,
  owner        uuid default auth.uid() references auth.users on delete set null
);

create table if not exists public.comments (
  id       text primary key default gen_random_uuid()::text,
  task_id  text not null,
  text     text not null,
  author   text not null default '',
  by_user  uuid default auth.uid(),
  at       bigint not null default 0
);

create table if not exists public.history (
  id       text primary key default gen_random_uuid()::text,
  task_id  text not null,
  text     text not null,
  title    text not null default '',
  author   text not null default '',
  at       bigint not null default 0
);

create table if not exists public.lists (
  id          text primary key default gen_random_uuid()::text,
  name        text not null,
  sort_order  double precision not null default 0
);

create table if not exists public.items (
  id             text primary key default gen_random_uuid()::text,
  list_id        text not null default 'groceries',
  name           text not null,
  qty            text not null default '',
  section        text not null default 'Other',
  checked        boolean not null default false,
  checked_at     bigint,
  bought         boolean not null default false,
  bought_at      bigint,
  task_id        text not null default '',
  added_by       text not null default '',
  added_by_user  uuid default auth.uid(),
  added_at       bigint not null default 0
);

-- What you have bought before: powers suggestions and remembered shop sections.
create table if not exists public.catalog (
  id       text primary key,
  name     text not null,
  section  text not null default 'Other',
  manual   boolean not null default false,
  count    integer not null default 0,
  last_at  bigint not null default 0,
  list_counts jsonb not null default '{}'::jsonb  -- per shopping list: {"<list id>": count}
);

-- Small shared settings, e.g. key 'people' = {"a": "...", "b": "...", "aUser": "<uuid>", "bUser": "<uuid>"}.
create table if not exists public.config (
  key    text primary key,
  value  jsonb not null default '{}'::jsonb
);

-- Per-person state ("what I've already seen"), private to each person.
create table if not exists public.user_state (
  user_id      uuid primary key default auth.uid() references auth.users on delete cascade,
  seen         jsonb not null default '{}'::jsonb,
  activity_at  bigint not null default 0,
  shopping_at  bigint not null default 0,
  today        jsonb not null default '{}'::jsonb  -- My day pins: {"<task id>": "YYYY-MM-DD"}
);

create index if not exists tasks_parent_id_idx on public.tasks (parent_id);
create index if not exists comments_task_id_idx on public.comments (task_id);
create index if not exists history_task_id_idx on public.history (task_id);
create index if not exists history_at_desc_idx on public.history (at desc);
create index if not exists items_task_id_idx on public.items (task_id);

-- ---------- access rules ----------

alter table public.tasks      enable row level security;
alter table public.comments   enable row level security;
alter table public.history    enable row level security;
alter table public.lists      enable row level security;
alter table public.items      enable row level security;
alter table public.catalog    enable row level security;
alter table public.config     enable row level security;
alter table public.user_state enable row level security;

-- Shared tasks for both of you; private tasks only for their owner.
drop policy if exists "tasks: shared or own private" on public.tasks;
create policy "tasks: shared or own private" on public.tasks
  for all to authenticated
  using (not private or owner = auth.uid())
  with check (not private or owner = auth.uid());

drop policy if exists "comments: signed-in users" on public.comments;
create policy "comments: signed-in users" on public.comments  for all to authenticated using (true) with check (true);
drop policy if exists "history: signed-in users" on public.history;
create policy "history: signed-in users" on public.history   for all to authenticated using (true) with check (true);
drop policy if exists "lists: signed-in users" on public.lists;
create policy "lists: signed-in users" on public.lists     for all to authenticated using (true) with check (true);
drop policy if exists "items: signed-in users" on public.items;
create policy "items: signed-in users" on public.items     for all to authenticated using (true) with check (true);
drop policy if exists "catalog: signed-in users" on public.catalog;
create policy "catalog: signed-in users" on public.catalog   for all to authenticated using (true) with check (true);
drop policy if exists "config: signed-in users" on public.config;
create policy "config: signed-in users" on public.config    for all to authenticated using (true) with check (true);

drop policy if exists "user_state: own row only" on public.user_state;
create policy "user_state: own row only" on public.user_state
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- ---------- live updates ----------
-- Changes are pushed to the open app instantly; the access rules above still apply to what each person receives.

do $$ begin
  alter publication supabase_realtime add table
    public.tasks, public.comments, public.history, public.lists,
    public.items, public.catalog, public.config, public.user_state;
exception when duplicate_object then null; end $$;

-- ======== 002_my_day.sql ========
-- My day: each person's tasks pinned for today, as {"<task id>": "YYYY-MM-DD"}.
-- Run once: Supabase dashboard > SQL Editor > New query > paste > Run.
-- Safe to run more than once. (Already included in schema.sql for new projects.)
alter table public.user_state add column if not exists today jsonb not null default '{}'::jsonb;

-- ======== 003_catalog_per_list.sql ========
-- Frequent items per shopping list: how often each item was added to each list, as {"<list id>": count}.
-- Run once: Supabase dashboard > SQL Editor > New query > paste > Run.
-- Safe to run more than once. (Already included in schema.sql for new projects.)
alter table public.catalog add column if not exists list_counts jsonb not null default '{}'::jsonb;

-- ======== 004_notifications.sql ========
-- Our Tasks: notifications, briefings and the briefing chat.
-- Run once: Supabase dashboard > SQL Editor > New query > paste this whole file > Run.
-- Safe to run more than once.

-- Devices that receive push notifications (one row per phone / Mac app). Each person sees only their own.
create table if not exists public.push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users on delete cascade,
  endpoint    text not null unique,
  p256dh      text not null,
  auth        text not null,
  device      text not null default '',
  created_at  timestamptz not null default now()
);
alter table public.push_subscriptions enable row level security;
drop policy if exists "push_subscriptions: own rows" on public.push_subscriptions;
create policy "push_subscriptions: own rows" on public.push_subscriptions
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Each person's notification settings. Times are local "HH:MM" in their time zone.
create table if not exists public.notify_prefs (
  user_id      uuid primary key default auth.uid() references auth.users on delete cascade,
  lang         text not null default 'en',             -- briefing language: en | pl (also added by 005)
  tz           text not null default 'Europe/Warsaw',
  morning      text not null default '07:30',   -- '' = no morning briefing
  evening      text not null default '20:00',   -- '' = no evening check
  quiet_from   text not null default '22:00',   -- no instant notifications between quiet_from and quiet_to
  quiet_to     text not null default '07:00',
  on_assigned  boolean not null default true,
  on_comment   boolean not null default true,
  on_closed    boolean not null default true,
  morning_sent text not null default '',        -- last local date a briefing went out (set by the server)
  evening_sent text not null default ''
);
alter table public.notify_prefs enable row level security;
drop policy if exists "notify_prefs: own row" on public.notify_prefs;
create policy "notify_prefs: own row" on public.notify_prefs
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Briefings and the conversation about them. Each person sees only their own.
create table if not exists public.briefings (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users on delete cascade,
  kind        text not null default 'chat',     -- morning | evening | chat
  role        text not null default 'user',     -- user | assistant
  text        text not null,
  actions     jsonb not null default '[]'::jsonb, -- changes Claude proposes; applied only when you confirm
  applied     boolean not null default false,
  created_at  timestamptz not null default now()
);
create index if not exists briefings_user_time on public.briefings (user_id, created_at desc);
alter table public.briefings enable row level security;
drop policy if exists "briefings: own rows" on public.briefings;
create policy "briefings: own rows" on public.briefings
  for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Server-only settings: the push signing keys and the timer's password. No policies = no access from the app;
-- only the notify function (with the service role) can read it.
create table if not exists public.push_config (
  id           int primary key default 1 check (id = 1),
  vapid        jsonb,
  cron_secret  text not null default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
);
alter table public.push_config enable row level security;
insert into public.push_config (id) values (1) on conflict (id) do nothing;

-- Timer: every 15 minutes, ask the notify function to send briefings that are due.
create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;
select cron.unschedule('our-tasks-notify') where exists (select 1 from cron.job where jobname = 'our-tasks-notify');
select cron.schedule('our-tasks-notify', '*/15 * * * *', $job$
  select net.http_post(
    url     := 'https://jwhuaaxrymdqwanwthvg.supabase.co/functions/v1/notify',
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'x-cron-secret', (select cron_secret from public.push_config where id = 1)),
    body    := '{"action":"tick"}'::jsonb
  );
$job$);

